WITH flattened_attrs AS (SELECT id, service, latency_ms, payload_json, context, GET_JSON_OBJECT(payload_json, '$.duration') AS duration_text, COALESCE(context['trace'], 'unknown') AS trace_or_default FROM app_logs) SELECT CASE WHEN latency_ms >= 1945 THEN 'LARGE' ELSE 'SMALL' END AS latency_ms_tier, service, COUNT(CASE WHEN service = 'search' THEN 1 END) AS search_count, PERCENTILE_APPROX(latency_ms, ARRAY(0.25, 0.5, 0.75)) AS latency_ms_quartiles, PERCENTILE_APPROX(latency_ms, 0.95) AS latency_ms_p95, COUNT(CASE WHEN service = 'billing' THEN 1 END) AS billing_count, SUM(latency_ms) FILTER (WHERE service = 'auth') AS auth_total_latency_ms FROM flattened_attrs GROUP BY latency_ms_tier, service ORDER BY latency_ms_tier DESC NULLS FIRST;
